import { ExternalTokenizer } from '@lezer/lr';

export const existsTokenizer = new ExternalTokenizer((inputStream) => {
  let currCharCode = inputStream.peek(0);

  if (currCharCode === 33) {
    inputStream.advance();
    currCharCode = inputStream.peek(0);
  }

  // Character is not '=' -> definitely not an exists operator.
  if (currCharCode !== 61) {
    return;
  }

  // If the '=' is not followed by ' *' or ' * ' -> definitely not an exists operator.
  if (
    !(
      inputStream.peek(1) === 32 &&
      inputStream.peek(2) === 42 &&
      (inputStream.peek(3) === -1 || inputStream.peek(3) === 32)
    )
  ) {
    return;
  }

  inputStream.acceptToken(2, 3);
});
